// 태그 관리 컴포넌트
import { useState, useEffect } from 'react';
import type { Tag } from '../types';
import * as store from '../stores/firestore';
import { useAuth } from '../contexts/AuthContext';
import './TagManager.css';

// 태그 색상 프리셋
const TAG_COLORS = [
  '#ef4444', '#f97316', '#eab308', '#22c55e', '#14b8a6',
  '#06b6d4', '#3b82f6', '#6366f1', '#8b5cf6', '#ec4899',
];

interface TagManagerProps {
  onClose: () => void;
}

// 태그 관리 모달
export function TagManagerModal({ onClose }: TagManagerProps) {
  const { isDemo } = useAuth();
  const [tags, setTags] = useState<Tag[]>([]);
  const [newTagName, setNewTagName] = useState('');
  const [newTagColor, setNewTagColor] = useState(TAG_COLORS[0]);
  const [editingTag, setEditingTag] = useState<Tag | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadTags();
  }, []);

  async function loadTags() {
    try {
      if (isDemo) {
        setTags([]);
      } else {
        const loaded = await store.getTags();
        setTags(loaded);
      }
    } catch (error) {
      console.error('Failed to load tags:', error);
    } finally {
      setLoading(false);
    }
  }

  async function handleCreateTag() {
    if (!newTagName.trim()) return;
    
    const now = Date.now();
    const tag: Tag = {
      id: store.generateId(),
      name: newTagName.trim(),
      color: newTagColor,
      createdAt: now,
      updatedAt: now,
    };

    try {
      if (!isDemo) {
        await store.saveTag(tag);
      }
      setTags([...tags, tag]);
      setNewTagName('');
      setNewTagColor(TAG_COLORS[Math.floor(Math.random() * TAG_COLORS.length)]);
    } catch (error) {
      console.error('Failed to create tag:', error);
    }
  }

  async function handleUpdateTag() {
    if (!editingTag || !editingTag.name.trim()) return;

    const updated = { ...editingTag, updatedAt: Date.now() };
    
    try {
      if (!isDemo) {
        await store.saveTag(updated);
      }
      setTags(tags.map(t => t.id === updated.id ? updated : t));
      setEditingTag(null);
    } catch (error) {
      console.error('Failed to update tag:', error);
    }
  }

  async function handleDeleteTag(tagId: string) {
    if (!confirm('이 태그를 삭제하시겠습니까?')) return;

    try {
      if (!isDemo) {
        await store.deleteTag(tagId);
      }
      setTags(tags.filter(t => t.id !== tagId));
    } catch (error) {
      console.error('Failed to delete tag:', error);
    }
  }

  return (
    <div className="tag-manager-overlay" onClick={onClose}>
      <div className="tag-manager-modal" onClick={e => e.stopPropagation()}>
        <div className="tag-manager-header">
          <h2>태그 관리</h2>
          <button className="close-btn" onClick={onClose}>✕</button>
        </div>

        <div className="tag-manager-body">
          {/* 새 태그 추가 */}
          <div className="tag-create-form">
            <input
              type="text"
              placeholder="새 태그 이름..."
              value={newTagName}
              onChange={e => setNewTagName(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleCreateTag()}
            />
            <div className="color-picker">
              {TAG_COLORS.map(color => (
                <button
                  key={color}
                  className={`color-option ${newTagColor === color ? 'selected' : ''}`}
                  style={{ backgroundColor: color }}
                  onClick={() => setNewTagColor(color)}
                />
              ))}
            </div>
            <button className="create-btn" onClick={handleCreateTag}>
              추가
            </button>
          </div>

          {/* 태그 목록 */}
          <div className="tag-list">
            {loading ? (
              <div className="loading">로딩 중...</div>
            ) : tags.length === 0 ? (
              <div className="empty">태그가 없습니다</div>
            ) : (
              tags.map(tag => (
                <div key={tag.id} className="tag-item">
                  {editingTag?.id === tag.id ? (
                    <div className="tag-edit-form">
                      <input
                        type="text"
                        value={editingTag.name}
                        onChange={e => setEditingTag({ ...editingTag, name: e.target.value })}
                        onKeyDown={e => e.key === 'Enter' && handleUpdateTag()}
                        autoFocus
                      />
                      <div className="color-picker small">
                        {TAG_COLORS.map(color => (
                          <button
                            key={color}
                            className={`color-option ${editingTag.color === color ? 'selected' : ''}`}
                            style={{ backgroundColor: color }}
                            onClick={() => setEditingTag({ ...editingTag, color })}
                          />
                        ))}
                      </div>
                      <button className="save-btn" onClick={handleUpdateTag}>저장</button>
                      <button className="cancel-btn" onClick={() => setEditingTag(null)}>취소</button>
                    </div>
                  ) : (
                    <>
                      <span 
                        className="tag-badge"
                        style={{ backgroundColor: tag.color }}
                      >
                        {tag.name}
                      </span>
                      <div className="tag-actions">
                        <button onClick={() => setEditingTag(tag)}>✏️</button>
                        <button onClick={() => handleDeleteTag(tag.id)}>🗑️</button>
                      </div>
                    </>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// 태그 선택 드롭다운
interface TagSelectorProps {
  selectedTags: string[];
  onChange: (tags: string[]) => void;
  allTags: Tag[];
}

export function TagSelector({ selectedTags, onChange, allTags }: TagSelectorProps) {
  const [isOpen, setIsOpen] = useState(false);

  const toggleTag = (tagId: string) => {
    if (selectedTags.includes(tagId)) {
      onChange(selectedTags.filter(id => id !== tagId));
    } else {
      onChange([...selectedTags, tagId]);
    }
  };

  const selectedTagObjects = allTags.filter(t => selectedTags.includes(t.id));

  return (
    <div className="tag-selector">
      <div className="selected-tags" onClick={() => setIsOpen(!isOpen)}>
        {selectedTagObjects.length === 0 ? (
          <span className="placeholder">태그 선택...</span>
        ) : (
          selectedTagObjects.map(tag => (
            <span 
              key={tag.id}
              className="tag-chip"
              style={{ backgroundColor: tag.color }}
            >
              {tag.name}
            </span>
          ))
        )}
        <span className="dropdown-arrow">{isOpen ? '▲' : '▼'}</span>
      </div>
      
      {isOpen && (
        <div className="tag-dropdown">
          {allTags.length === 0 ? (
            <div className="no-tags">태그가 없습니다</div>
          ) : (
            allTags.map(tag => (
              <label key={tag.id} className="tag-option">
                <input
                  type="checkbox"
                  checked={selectedTags.includes(tag.id)}
                  onChange={() => toggleTag(tag.id)}
                />
                <span 
                  className="tag-chip"
                  style={{ backgroundColor: tag.color }}
                >
                  {tag.name}
                </span>
              </label>
            ))
          )}
        </div>
      )}
    </div>
  );
}

// 태그 필터 (MonthlyPage용)
interface TagFilterProps {
  tags: Tag[];
  selectedTagIds: string[];
  onChange: (tagIds: string[]) => void;
}

export function TagFilter({ tags, selectedTagIds, onChange }: TagFilterProps) {
  const toggleTag = (tagId: string) => {
    if (selectedTagIds.includes(tagId)) {
      onChange(selectedTagIds.filter(id => id !== tagId));
    } else {
      onChange([...selectedTagIds, tagId]);
    }
  };

  if (tags.length === 0) return null;

  return (
    <div className="tag-filter">
      {tags.map(tag => (
        <button
          key={tag.id}
          className={`tag-filter-btn ${selectedTagIds.includes(tag.id) ? 'active' : ''}`}
          style={{ 
            '--tag-color': tag.color,
            backgroundColor: selectedTagIds.includes(tag.id) ? tag.color : 'transparent',
            borderColor: tag.color,
            color: selectedTagIds.includes(tag.id) ? 'white' : tag.color,
          } as React.CSSProperties}
          onClick={() => toggleTag(tag.id)}
        >
          {tag.name}
        </button>
      ))}
    </div>
  );
}
