// 스케줄 데이터 관리 훅 (Firestore 저장)
import { useState, useEffect, useCallback } from 'react';
import * as store from '../stores/firestore';
import type { ScheduleEvent, TodoItem, DaySummary, RecurringEvent, RecurrenceRule } from '../types';
import { getRecurringEventsForDate, createRecurringEvent } from '../utils/recurrence';
import { isDemoMode, generateDemoEvents, generateDemoTodos } from '../utils/demoData';

export function useScheduleStore(date: string) {
  const [events, setEvents] = useState<ScheduleEvent[]>([]);
  const [recurringEvents, setRecurringEvents] = useState<RecurringEvent[]>([]);
  const [todos, setTodos] = useState<TodoItem[]>([]);
  const [daySummary, setDaySummary] = useState<DaySummary | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // 데모 모드 여부 저장
  const [isDemo] = useState(isDemoMode());

  // 데이터 로드
  useEffect(() => {
    async function loadData() {
      setIsLoading(true);
      try {
        // 데모 모드면 샘플 데이터 사용
        if (isDemo) {
          setEvents(generateDemoEvents(date));
          setRecurringEvents([]);
          setTodos(generateDemoTodos(date));
          setDaySummary({
            date,
            wakeUp: '07:00',
            sleep: '23:00',
            goal: '오늘 할 일을 모두 끝내자! 🎯',
            updatedAt: Date.now(),
          });
          setIsLoading(false);
          return;
        }

        // 모든 이벤트 로드
        const allEvents = await store.getEvents();
        
        // 해당 날짜에 시작하는 이벤트 또는 해당 날짜를 걸쳐있는 이벤트
        const dayEvents = allEvents.filter(e => {
          if (e.recurrenceId) return false;
          if (e.date === date) return true;
          if (e.endDate && e.date <= date && e.endDate >= date) return true;
          return false;
        });
        
        // 반복 이벤트 로드
        const allRecurring = await store.getRecurringEvents();
        setRecurringEvents(allRecurring);
        
        // 반복 이벤트에서 해당 날짜 인스턴스 생성
        const recurringInstances = getRecurringEventsForDate(allRecurring, date);
        
        // 일반 이벤트 + 반복 이벤트 인스턴스 병합
        setEvents([...dayEvents, ...recurringInstances]);

        // 해당 날짜의 To-do 로드
        const dayTodos = await store.getTodosByDate(date);
        setTodos(dayTodos);

        // Day summary 로드
        const summary = await store.getDaySummary(date);
        setDaySummary(summary || {
          date,
          wakeUp: null,
          sleep: null,
          goal: '',
          updatedAt: Date.now(),
        });
      } catch (error) {
        console.error('Failed to load data:', error);
      } finally {
        setIsLoading(false);
      }
    }

    loadData();
  }, [date]);

  // 이벤트 생성
  const createEvent = useCallback(async (event: ScheduleEvent) => {
    try {
      console.log('Creating event:', event);
      // 데모 모드면 로컬 상태만 업데이트
      if (!isDemo) {
        await store.saveEvent(event);
      }
      console.log('Event saved successfully');
      setEvents(prev => {
        // 중복 체크 (같은 ID가 이미 있으면 추가하지 않음)
        if (prev.some(e => e.id === event.id)) {
          return prev.map(e => e.id === event.id ? event : e);
        }
        return [...prev, event];
      });
    } catch (error) {
      console.error('Failed to create event:', error);
      alert('일정 저장 실패: ' + (error as Error).message);
    }
  }, [isDemo]);

  // 이벤트 업데이트
  const updateEvent = useCallback(async (event: ScheduleEvent) => {
    try {
      console.log('Updating event:', event);
      // 반복 이벤트 인스턴스인 경우 별도 처리
      if (event.recurrenceId) {
        // recurrenceId를 제거한 새 이벤트 생성 (undefined 대신 delete 사용)
        const newEvent = { ...event, id: store.generateId() };
        delete newEvent.recurrenceId;
        if (!isDemo) {
          await store.saveEvent(newEvent);
        }
        setEvents(prev => prev.map(e => e.id === event.id ? newEvent : e));
      } else {
        if (!isDemo) {
          await store.saveEvent(event);
        }
        setEvents(prev => prev.map(e => e.id === event.id ? event : e));
      }
      console.log('Event updated successfully');
    } catch (error) {
      console.error('Failed to update event:', error);
      alert('일정 업데이트 실패: ' + (error as Error).message);
    }
  }, [isDemo]);

  // 이벤트 삭제
  const deleteEvent = useCallback(async (eventId: string) => {
    try {
      if (!isDemo) {
        await store.deleteEvent(eventId);
      }
      setEvents(prev => prev.filter(e => e.id !== eventId));
    } catch (error) {
      console.error('Failed to delete event:', error);
    }
  }, [isDemo]);

  // 반복 이벤트 생성
  const createRecurring = useCallback(async (
    title: string,
    start: string,
    end: string,
    color: string,
    note: string,
    rule: RecurrenceRule
  ) => {
    try {
      const recurring = createRecurringEvent(title, start, end, color, note, rule);
      if (!isDemo) {
        await store.saveRecurringEvent(recurring);
      }
      setRecurringEvents(prev => [...prev, recurring]);
      
      // 현재 날짜에 해당하는 인스턴스 추가
      const instances = getRecurringEventsForDate([recurring], date);
      if (instances.length > 0) {
        setEvents(prev => [...prev, ...instances]);
      }
    } catch (error) {
      console.error('Failed to create recurring event:', error);
    }
  }, [date, isDemo]);

  // 반복 이벤트 삭제
  const deleteRecurring = useCallback(async (recurringId: string) => {
    try {
      if (!isDemo) {
        await store.deleteRecurringEvent(recurringId);
      }
      setRecurringEvents(prev => prev.filter(r => r.id !== recurringId));
      setEvents(prev => prev.filter(e => e.recurrenceId !== recurringId));
    } catch (error) {
      console.error('Failed to delete recurring event:', error);
    }
  }, [isDemo]);

  // To-do 생성
  const createTodo = useCallback(async (title: string) => {
    const todo: TodoItem = {
      id: store.generateId(),
      date,
      title,
      status: 'active',
      note: '',
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };

    try {
      if (!isDemo) {
        await store.saveTodo(todo);
      }
      setTodos(prev => [...prev, todo]);
    } catch (error) {
      console.error('Failed to create todo:', error);
    }
  }, [date, isDemo]);

  // To-do 업데이트
  const updateTodo = useCallback(async (todo: TodoItem) => {
    try {
      if (!isDemo) {
        await store.saveTodo(todo);
      }
      setTodos(prev => prev.map(t => t.id === todo.id ? todo : t));
    } catch (error) {
      console.error('Failed to update todo:', error);
    }
  }, [isDemo]);

  // To-do 삭제
  const deleteTodo = useCallback(async (todoId: string) => {
    try {
      if (!isDemo) {
        await store.deleteTodo(todoId);
      }
      setTodos(prev => prev.filter(t => t.id !== todoId));
    } catch (error) {
      console.error('Failed to delete todo:', error);
    }
  }, [isDemo]);

  // Day summary 업데이트
  const updateDaySummary = useCallback(async (updates: Partial<DaySummary>) => {
    const updated: DaySummary = {
      ...daySummary,
      date,
      wakeUp: daySummary?.wakeUp ?? null,
      sleep: daySummary?.sleep ?? null,
      goal: daySummary?.goal ?? '',
      ...updates,
      updatedAt: Date.now(),
    };

    try {
      if (!isDemo) {
        await store.saveDaySummary(updated);
      }
      setDaySummary(updated);
    } catch (error) {
      console.error('Failed to update day summary:', error);
    }
  }, [date, daySummary, isDemo]);

  return {
    events,
    recurringEvents,
    todos,
    daySummary,
    isLoading,
    createEvent,
    updateEvent,
    deleteEvent,
    createRecurring,
    deleteRecurring,
    createTodo,
    updateTodo,
    deleteTodo,
    updateDaySummary,
  };
}
